import java.io.*;
import java.util.*;

public class Main {
    static int[] parent;
    static int[] size;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static class State implements Comparable<State> {
        long dist;
        int node;

        State(long dist, int node) {
            this.dist = dist;
            this.node = node;
        }

        public int compareTo(State other) {
            return Long.compare(this.dist, other.dist);
        }
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int nextInt() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return Integer.parseInt(st.nextToken());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        int[] price = new int[K + 1];
        for (int i = 1; i <= K; i++) {
            price[i] = fs.nextInt();
        }

        int[] edgeU = new int[M];
        int[] edgeV = new int[M];
        int[] nextGroup = new int[M];
        int[] headColor = new int[K + 1];
        Arrays.fill(headColor, -1);

        for (int i = 0; i < M; i++) {
            edgeU[i] = fs.nextInt();
            edgeV[i] = fs.nextInt();
            int color = fs.nextInt();

            nextGroup[i] = headColor[color];
            headColor[color] = i;
        }

        int A = fs.nextInt();
        int B = fs.nextInt();

        parent = new int[N + 1];
        Arrays.fill(parent, -1);

        size = new int[N + 1];
        int[] rootComponent = new int[N + 1];

        int[] touched = new int[N + 1];
        int[] roots = new int[N + 1];

        int maxNodes = N + M + 5;
        int maxEdges = 8 * M + 20;

        int[] headGraph = new int[maxNodes];
        Arrays.fill(headGraph, -1);

        int[] to = new int[maxEdges];
        int[] weight = new int[maxEdges];
        int[] nextGraph = new int[maxEdges];

        int edgeCount = 0;
        int componentCount = 0;

        for (int color = 1; color <= K; color++) {
            int firstEdge = headColor[color];
            if (firstEdge == -1) continue;

            int touchedCount = 0;
            int rootCount = 0;

            for (int e = firstEdge; e != -1; e = nextGroup[e]) {
                int u = edgeU[e];
                int v = edgeV[e];

                if (parent[u] == -1) {
                    parent[u] = u;
                    size[u] = 1;
                    touched[touchedCount++] = u;
                }

                if (parent[v] == -1) {
                    parent[v] = v;
                    size[v] = 1;
                    touched[touchedCount++] = v;
                }

                int ru = find(u);
                int rv = find(v);

                if (ru != rv) {
                    if (size[ru] < size[rv]) {
                        int temp = ru;
                        ru = rv;
                        rv = temp;
                    }

                    parent[rv] = ru;
                    size[ru] += size[rv];
                }
            }

            int currentPrice = price[color];

            for (int i = 0; i < touchedCount; i++) {
                int station = touched[i];
                int root = find(station);

                int component = rootComponent[root];

                if (component == 0) {
                    component = ++componentCount;
                    rootComponent[root] = component;
                    roots[rootCount++] = root;
                }

                int componentNode = N + component;

                to[edgeCount] = componentNode;
                weight[edgeCount] = currentPrice;
                nextGraph[edgeCount] = headGraph[station];
                headGraph[station] = edgeCount++;

                to[edgeCount] = station;
                weight[edgeCount] = 0;
                nextGraph[edgeCount] = headGraph[componentNode];
                headGraph[componentNode] = edgeCount++;
            }

            for (int i = 0; i < touchedCount; i++) {
                parent[touched[i]] = -1;
            }

            for (int i = 0; i < rootCount; i++) {
                rootComponent[roots[i]] = 0;
            }
        }

        int totalNodes = N + componentCount;
        long INF = Long.MAX_VALUE / 4;

        long[] dist = new long[totalNodes + 1];
        Arrays.fill(dist, INF);

        PriorityQueue<State> pq = new PriorityQueue<>();

        dist[A] = 0;
        pq.add(new State(0, A));

        while (!pq.isEmpty()) {
            State current = pq.poll();

            if (current.dist != dist[current.node]) continue;
            if (current.node == B) break;

            for (int e = headGraph[current.node]; e != -1; e = nextGraph[e]) {
                int next = to[e];
                long newDist = current.dist + weight[e];

                if (newDist < dist[next]) {
                    dist[next] = newDist;
                    pq.add(new State(newDist, next));
                }
            }
        }

        long answer = dist[B];

        if (answer >= INF / 2) {
            answer = -1;
        }

        System.out.println(answer);
    }
}
